var a=[{title:`Definições`,text:`Um superset antagonista alterna padrões de movimento opostos, como um press seguido de uma remada. Uma série composta combina dois exercícios para o mesmo grupo muscular. Um circuito pode passar por cinco estações antes de descansar e repetir. EMOM significa “a cada minuto, no minuto” e AMRAP significa “o máximo de rondas ou repetições possível” num tempo definido.`},{title:`Porquê usá-los`,text:`Combinar um empurrar com um puxar permite que um grupo muscular trabalhe enquanto outro descansa, o que pode poupar tempo. Os circuitos podem combinar trabalho de resistência e cardio num espaço pequeno. Muitas pessoas pensam que desenvolvem mais força ou músculo, mas não o fazem automaticamente; a qualidade do trabalho total e a sua recuperação continuam a decidir isso.`},{title:`Gerir a fadiga`,text:`Um agachamento pesado combinado com um peso morto difícil pode piorar ambos os levantamentos, sobretudo para iniciantes. Combine exercícios que não compitam demasiado entre si e descanse o suficiente para manter o controlo. Os levantamentos técnicos e os saltos explosivos costumam precisar de mais recuperação do que um circuito cronometrado dá. Use supersets quando tiver pouco tempo e a combinação fizer sentido para o seu objetivo. Não corte o descanso só para cumprir um tempo e dispense circuitos cheios de saltos ou de movimentos difíceis se o seu espaço, os limites de ruído ou o seu corpo os excluírem.`},{title:`Exemplo`,text:`Faça dez flexões inclinadas controladas, depois dez remadas com apoio e descanse 90 segundos; repita três vezes. Um circuito de condicionamento pode usar subidas a um degrau, uma caminhada leve com carga e marcha, com descanso planeado. Escolha um número de rondas que consiga manter sem se precipitar para uma técnica fraca.`}];var s=[{label:`NSCA: treino eficiente em termos de tempo`,url:`https://www.nsca.com/education/articles/ptq/time-efficient-training`},{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NSCA: segurança e fundamentos do treino de resistência`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var i={sections:a,sources:s};export{i as default,a as sections,s as sources};